mapper.select:
SELECT * FROM article_study_record
WHERE deleted = 0

    AND article_id = #{articleId}


    AND employee_id = #{employeeId}


    AND study_status = #{studyStatus}


    AND quiz_status = #{quizStatus}


    AND article_category = #{category}


    AND (LOWER(employee_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(employee_no) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(article_title) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(store_name) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

ORDER BY create_time DESC
